-- =====================================================================================
-- V1: core (non-ledger) schema.
-- The ledger tables (transactions, ledger_entries) and their triggers live in V2.
-- deposits is added in Phase 2 / Step 8 because it has a FK to transactions.
--
-- Conventions:
--   * Public IDs are UUIDs generated by the application (v7, time-ordered). No DB default,
--     so a missing ID is a bug that fails loudly instead of silently getting a random v4.
--   * All timestamps are TIMESTAMPTZ. Defaults exist as a safety net; the app sets them
--     explicitly from its injected Clock.
--   * Enumerations are TEXT + CHECK rather than Postgres ENUM types: adding a value is
--     a simple constraint swap, and Hibernate maps them as plain strings.
-- =====================================================================================

-- Case-insensitive email: 'Alice@x.com' and 'alice@x.com' are the same user.
CREATE EXTENSION IF NOT EXISTS citext;

-- -------------------------------------------------------------------------------------
-- users
-- -------------------------------------------------------------------------------------
CREATE TABLE users (
    id            UUID        PRIMARY KEY,
    email         CITEXT      NOT NULL UNIQUE,
    password_hash TEXT        NOT NULL,
    role          TEXT        NOT NULL CHECK (role IN ('CUSTOMER', 'SUPPORT', 'ADMIN')),
    status        TEXT        NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'FROZEN')),
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- -------------------------------------------------------------------------------------
-- refresh_tokens: we store only SHA-256(token). A DB leak does not leak usable tokens.
-- family_id groups a chain of rotations so reuse of an old token can revoke the chain.
-- -------------------------------------------------------------------------------------
CREATE TABLE refresh_tokens (
    id          UUID        PRIMARY KEY,
    user_id     UUID        NOT NULL REFERENCES users (id),
    token_hash  BYTEA       NOT NULL UNIQUE CHECK (octet_length(token_hash) = 32),
    family_id   UUID        NOT NULL,
    expires_at  TIMESTAMPTZ NOT NULL,
    revoked_at  TIMESTAMPTZ NULL,
    replaced_by UUID        NULL REFERENCES refresh_tokens (id),
    user_agent  TEXT        NULL,
    ip          TEXT        NULL,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX ix_refresh_tokens_family ON refresh_tokens (family_id);
CREATE INDEX ix_refresh_tokens_user   ON refresh_tokens (user_id);

-- -------------------------------------------------------------------------------------
-- accounts: the chart of accounts. A user wallet and a system account are both "accounts"
-- so every ledger leg points at the same table.
-- There is deliberately NO balance column that the app writes freely. cached_balance is
-- optional and, if used, is only ever updated in the same transaction as the ledger insert
-- (decision recorded in Step 5).
-- -------------------------------------------------------------------------------------
CREATE TABLE accounts (
    id             UUID        PRIMARY KEY,
    owner_user_id  UUID        NULL REFERENCES users (id),
    type           TEXT        NOT NULL CHECK (type IN ('USER_WALLET', 'SYSTEM')),
    system_code    TEXT        NULL
                   CHECK (system_code IN ('EXTERNAL_FUNDING', 'REFUNDS_CLEARING', 'FX_CLEARING')),
    currency       CHAR(3)     NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
    name           TEXT        NOT NULL,
    status         TEXT        NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'FROZEN', 'CLOSED')),
    cached_balance BIGINT      NULL,
    version        BIGINT      NOT NULL DEFAULT 0,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),

    -- A wallet has an owner and no system code; a system account is the opposite.
    CONSTRAINT ck_accounts_shape CHECK (
        (type = 'USER_WALLET' AND owner_user_id IS NOT NULL AND system_code IS NULL)
     OR (type = 'SYSTEM'      AND owner_user_id IS NULL     AND system_code IS NOT NULL)
    )
);
-- Exactly one EXTERNAL_FUNDING (etc.) account per currency.
CREATE UNIQUE INDEX ux_accounts_system_code_currency
    ON accounts (system_code, currency) WHERE type = 'SYSTEM';
CREATE INDEX ix_accounts_owner ON accounts (owner_user_id);

-- -------------------------------------------------------------------------------------
-- idempotency_keys: reserved BEFORE any state change; replayed on retries.
-- -------------------------------------------------------------------------------------
CREATE TABLE idempotency_keys (
    id              UUID        PRIMARY KEY,
    user_id         UUID        NOT NULL REFERENCES users (id),
    key             TEXT        NOT NULL CHECK (length(key) BETWEEN 1 AND 255),
    request_method  TEXT        NOT NULL,
    request_path    TEXT        NOT NULL,
    request_hash    TEXT        NOT NULL CHECK (request_hash ~ '^[0-9a-f]{64}$'), -- hex SHA-256
    status          TEXT        NOT NULL CHECK (status IN ('IN_PROGRESS', 'COMPLETED')),
    response_status INT         NULL,
    response_body   JSONB       NULL,
    locked_at       TIMESTAMPTZ NOT NULL,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at      TIMESTAMPTZ NOT NULL,

    CONSTRAINT ux_idempotency_keys_user_key UNIQUE (user_id, key)
);
CREATE INDEX ix_idempotency_keys_expires ON idempotency_keys (expires_at);

-- -------------------------------------------------------------------------------------
-- webhook_events: every inbound webhook is stored, including rejected ones (forensics).
-- -------------------------------------------------------------------------------------
CREATE TABLE webhook_events (
    id                UUID        PRIMARY KEY,
    provider          TEXT        NOT NULL,
    provider_event_id TEXT        NOT NULL,
    event_type        TEXT        NOT NULL,
    payload           JSONB       NOT NULL,
    signature         TEXT        NULL,
    status            TEXT        NOT NULL CHECK (status IN ('RECEIVED', 'PROCESSED', 'REJECTED', 'FAILED')),
    error             TEXT        NULL,
    received_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    processed_at      TIMESTAMPTZ NULL,

    CONSTRAINT ux_webhook_events_provider_event UNIQUE (provider, provider_event_id)
);
CREATE INDEX ix_webhook_events_status_received ON webhook_events (status, received_at);

-- -------------------------------------------------------------------------------------
-- reconciliation_runs
-- (column is "trigger_type", not "trigger", to avoid quoting a SQL keyword everywhere)
-- -------------------------------------------------------------------------------------
CREATE TABLE reconciliation_runs (
    id                   UUID        PRIMARY KEY,
    trigger_type         TEXT        NOT NULL CHECK (trigger_type IN ('SCHEDULED', 'MANUAL')),
    started_at           TIMESTAMPTZ NOT NULL,
    finished_at          TIMESTAMPTZ NULL,
    status               TEXT        NOT NULL CHECK (status IN ('RUNNING', 'PASSED', 'FAILED')),
    total_debits         BIGINT      NULL,
    total_credits        BIGINT      NULL,
    checked_transactions BIGINT      NULL,
    mismatches           JSONB       NULL
);
CREATE INDEX ix_reconciliation_runs_started ON reconciliation_runs (started_at DESC);

-- -------------------------------------------------------------------------------------
-- audit_log: who did what, to which entity, from where.
-- actor_user_id has no FK on purpose: the audit trail must accept events about
-- unknown/failed actors (e.g. login attempts) and must never block on user changes.
-- -------------------------------------------------------------------------------------
CREATE TABLE audit_log (
    id             BIGSERIAL   PRIMARY KEY,
    actor_user_id  UUID        NULL,
    action         TEXT        NOT NULL,
    entity_type    TEXT        NULL,
    entity_id      TEXT        NULL,
    details        JSONB       NULL,
    ip             TEXT        NULL,
    correlation_id TEXT        NULL,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX ix_audit_log_entity ON audit_log (entity_type, entity_id, created_at);
CREATE INDEX ix_audit_log_actor  ON audit_log (actor_user_id, created_at);

-- -------------------------------------------------------------------------------------
-- shedlock: standard table for ShedLock's JDBC provider (one job run across N instances).
-- -------------------------------------------------------------------------------------
CREATE TABLE shedlock (
    name       VARCHAR(64)  NOT NULL PRIMARY KEY,
    lock_until TIMESTAMPTZ  NOT NULL,
    locked_at  TIMESTAMPTZ  NOT NULL,
    locked_by  VARCHAR(255) NOT NULL
);
